import type { BotTemplate, Category, Industry, NeedKind, Prop } from "../template";

const BASE = ["post_to_room", "hand_off", "flag", "remember", "recall"];

// Short constructor: tools are space separated (the team basics are added), schedule is "HH:MM", minutes or null.
function t(
  id: string, name: string, role: string, title: string, hue: number, prop: Prop, category: Category,
  industries: Industry[], starter: Industry[], needs: NeedKind[], tools: string, schedule: string | number | null, task: string, instructions: string,
): BotTemplate {
  return {
    id, name, role, title, hue, prop, category, industries, starter: starter.length ? starter : undefined, needs,
    instructions, tier: "flash",
    tools: [...new Set([...BASE, ...tools.split(" ")])],
    schedule: schedule === null ? null : typeof schedule === "string" ? { dailyAt: schedule } : { everyMinutes: schedule },
    scheduledTask: schedule === null ? undefined : task,
  };
}

